mapper.select:
SELECT u.user_id, u.dept_id, d.dept_name, u.username, u.nickname, u.email, u.phone, u.sex, u.status, u.remark, u.create_time FROM sys_user u LEFT JOIN sys_dept d ON d.dept_id = u.dept_id AND d.del_flag = 0 WHERE u.del_flag = 0
AND u.username LIKE CONCAT('%', #{q.username}, '%')
AND u.nickname LIKE CONCAT('%', #{q.nickname}, '%')
AND u.phone LIKE CONCAT('%', #{q.phone}, '%')
AND u.status = #{q.status}
AND u.dept_id IN ( SELECT dept_id FROM sys_dept WHERE dept_id = #{q.deptId} OR FIND_IN_SET(#{q.deptId}, ancestors) )
AND u.create_time >= #{q.beginTime}
AND u.create_time <= #{q.endTime}
ORDER BY u.create_time DESC
